  'activity.auth.reset.redeem': 'A password reset code was used',
  'activity.auth.reset.redeem.failed': 'A wrong or expired reset code was entered',
  'activity.auth.magic.redeem': 'A sign-in code was used',
  'activity.auth.magic.redeem.failed': 'A wrong or expired sign-in code was entered',
  'activity.auth.other': 'An account security event',
  'activity.auth.other.failed': 'An account security event did not complete',
