  'activity.request.made.failed': 'Adding or sending something did not go through ({path})',
  'activity.request.changed': 'You changed something ({path})',
  'activity.request.changed.failed': 'A change did not go through ({path})',
  'activity.request.removed': 'You removed something ({path})',
  'activity.request.removed.failed': 'Removing something did not go through ({path})',
  'activity.request.read': 'You opened something ({path})',
